/**
 * @file Policies and Traditions subscreen
 * @copyright 2026 Firaxis Games
 * @description Handles player interaction for placing policies and traditions
 */

import { Component, createEffect, createMemo, For, onMount, ParentComponent, Show } from "solid-js";

import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { InnerFrame } from "#core/ui-next/components/inner-frame.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { PanelProps } from "#core/ui-next/components/panel.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { HSlot, SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { NestedTooltipContext } from "#core/ui-next/components/tooltip-nested.jsx";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { isMobile } from "#core/ui-next/services/view-experience.js";
import { LayoutModel } from "#core/ui-next/utilities/layout-utilities.js";

import { PoliciesModel } from "#base/ui/policies/model-policies.js";
import {
	activePolicyCards,
	activeTraditionCards,
	availablePolicyCards,
	availableTraditionCards,
	calculateGovtCardHeights,
	maxGovtCardHeight,
	setActivePolicyCards,
	setActiveTraditionCards,
	setAvailablePolicyCards,
	setAvailableTraditionCards,
} from "#base/ui/policies/policies-support.js";
import { CardSlot, PolicyCard } from "#base/ui/policies/policy-card.jsx";

export const PoliciesAndTraditions: ParentComponent<PanelProps> = () => {
	let root: HTMLDivElement | undefined;
	const policyModel = PoliciesModel.get();
	const layout = LayoutModel.get();

	onMount(() => {
		policyModel.clearArrays();
		setActivePolicyCards(policyModel.activePolicies);
		setAvailablePolicyCards(policyModel.availablePolicies);
		setActiveTraditionCards(policyModel.activeTraditions);
		setAvailableTraditionCards(policyModel.availableTraditions);

		if (root) {
			createEffect(() => {
				calculateGovtCardHeights(root);
			});
		}
	});

	const activeTraditionsWithEmpties = createMemo(() => {
		return Array(policyModel.tradSlots - activeTraditionCards.length).fill(0);
	});

	const allActive = createMemo(() => [
		...activeTraditionCards,
		...activeTraditionsWithEmpties(),
		...activePolicyCards,
	]);

	//resize cards if screen size changes
	createEffect(() => {
		layout.screenWidth();
		layout.screenHeight();

		if (root) {
			calculateGovtCardHeights(root);
		}
	});

	const newCardsThisTurn = policyModel.newCards;

	return (
		<NestedTooltipContext.Provider value={{ disabled: true }}>
			<div
				class={`flex-auto flex flex-col px-1 ${IsControllerActive() ? (isMobile() ? "pb-10" : "") : "pb-4"}`}
				ref={root}
			>
				<Show when={!policyModel.isSmallScreen()}>
					<div class="flex pt-4 pb-2 justify-center">
						<L10n.Stylize text={"LOC_UI_POLICIES_DESCRIPTION"} />
					</div>
				</Show>
				<HSlot
					name="policies-traditions"
					class="p-3 flex-auto flex flex-row w-full"
				>
					<InnerFrame
						class={`py-3 px-5 h-full ${policyModel.isSmallScreen() ? "policies__left" : "flex-1"} mr-2`}
					>
						<div class="flex flex-row w-full pr-5">
							<PoliciesCountSubHeader
								text={"LOC_UI_POLICIES_AVAILABLE"}
								isPolicy={true}
								count={availablePolicyCards.length.toString()}
							/>
							<PoliciesCountSubHeader
								text={"LOC_UI_TRADITIONS_AVAILABLE"}
								count={availableTraditionCards.length.toString()}
							/>
						</div>
						<ScrollArea
							class={"flex-auto"}
							reserveSpace={true}
						>
							<SpatialSlot
								name="inactive-policies"
								class="flex w-full"
								tabIndex={1}
							>
								<div class={"flex relative flex-1 flex-col items-center justify-start"}>
									<div class="flex flex-auto w-full flex-col items-center">
										<For each={availablePolicyCards}>
											{(item) => (
												<PolicyCard
													style={{ height: `${maxGovtCardHeight()}` }}
													name={item.Name}
													description={item.Description}
													card={item}
													isActive={false}
													tradSlot={false}
													isTradition={item.CultureSlotType == "TRADITION_CULTURE_SLOT"}
													isNewCard={newCardsThisTurn.includes(item)}
													autoFocus={policyModel.autoFocusCard == item.$index}
												/>
											)}
										</For>
									</div>
								</div>
								<div class={"flex relative flex-1 flex-col items-center justify-start"}>
									<div class="flex flex-auto w-full flex-col items-center">
										<For each={availableTraditionCards}>
											{(item) => (
												<PolicyCard
													style={{ height: `${maxGovtCardHeight()}` }}
													name={item.Name}
													description={item.Description}
													card={item}
													isActive={false}
													tradSlot={false}
													isTradition={item.CultureSlotType == "TRADITION_CULTURE_SLOT"}
													isNewCard={newCardsThisTurn.includes(item)}
													autoFocus={policyModel.autoFocusCard == item.$index}
												/>
											)}
										</For>
									</div>
								</div>
							</SpatialSlot>
						</ScrollArea>
					</InnerFrame>

					<InnerFrame
						class={`py-3 px-5 h-full ${policyModel.isSmallScreen() ? "policies__right" : "flex-1"} ml-2`}
					>
						<div class={"flex flex-row mr-1 w-full"}>
							<PoliciesCountSubHeader
								text={
									policyModel.isSmallScreen()
										? "LOC_UI_QUEUE_ACTIVE"
										: "LOC_UI_POLICIES_POLICIES_ACTIVE"
								}
								count={
									activePolicyCards.length +
									activeTraditionCards.length +
									" / " +
									(policyModel.policySlots + policyModel.tradSlots)
								}
							/>
						</div>
						<ScrollArea
							class={"flex-auto"}
							reserveSpace={true}
						>
							<SpatialSlot
								name="active-policies"
								class="active-policies-traditions"
								tabIndex={2}
							>
								<div class="flex flex-auto policies-2-col self-center max-w-full">
									<div
										class={
											"relative flex top-0 relative flex-wrap items-center w-full justify-start"
										}
									>
										<div
											class={
												"absolute top-0 flex pointer-events-none flex-wrap w-full items-center justify-start"
											}
										>
											<For each={Array(policyModel.tradSlots).fill(0)}>
												{() => (
													<CardSlot
														slotType={"TRADITION_CULTURE_SLOT"}
														style={{ height: `${maxGovtCardHeight()}` }}
													/>
												)}
											</For>
											<For each={Array(policyModel.policySlots).fill(0)}>
												{() => (
													<CardSlot
														slotType={"POLICY_CULTURE_SLOT"}
														style={{ height: `${maxGovtCardHeight()}` }}
													/>
												)}
											</For>
										</div>

										<For each={allActive()}>
											{(item) => (
												<PolicyCard
													style={{ height: `${maxGovtCardHeight()}` }}
													name={item.Name}
													description={item.Description}
													card={item}
													isActive={true}
													tradSlot={activeTraditionCards.includes(item)}
													isTradition={item.CultureSlotType == "TRADITION_CULTURE_SLOT"}
													isNewCard={newCardsThisTurn.includes(item.TraditionType)}
													autoFocus={policyModel.autoFocusCard == item.$index}
												/>
											)}
										</For>
									</div>
								</div>
							</SpatialSlot>
						</ScrollArea>
					</InnerFrame>
				</HSlot>

				<div
					class={`${policyModel.canSwapPolicies ? "" : "hidden"} ${IsControllerActive() ? "" : "my-4"} flex flex-row justify-center`}
				>
					<Show when={policyModel.canSwapPolicies}>
						<AudioContextProvider segment="PolicyConfirmButton">
							<Button
								class={`flex w-72 mr-6 `}
								onActivate={policyModel.onConfirmClick}
								disabled={policyModel.confirmDisable}
								classList={{
									hidden: IsControllerActive(),
								}}
								disableFocus={IsControllerActive()}
								hotkeyAction="shell-action-1"
								navTrayText="LOC_GENERIC_CONFIRM"
							>
								<L10n.Compose text={"LOC_GENERIC_CONFIRM"} />
							</Button>
						</AudioContextProvider>
					</Show>

					<Button
						class={"flex w-72"}
						onActivate={policyModel.onCloseClick}
						disabled={policyModel.confirmDisable}
						classList={{
							hidden: IsControllerActive(),
						}}
						disableFocus={IsControllerActive()}
						navTrayText="LOC_GENERIC_BACK"
						hotkeyAction="cancel"
					>
						<L10n.Compose text={"LOC_GENERIC_CANCEL"} />
					</Button>
				</div>
			</div>
		</NestedTooltipContext.Provider>
	);
};

interface PoliciesCountSubHeaderProps {
	text: string;
	count?: string;
	isPolicy?: boolean;
}

const PoliciesCountSubHeader: Component<PoliciesCountSubHeaderProps> = (props) => {
	return (
		<div
			class={`flex flex-auto flex-col items-center font-title tracking-100 w-full uppercase justify-center ${props.isPolicy ? "policies-text-color" : "text-secondary pb-3 pt-2"}`}
		>
			<div class="flex flex-row">
				<div class="text-accent-1 font-bold mr-2">{props.count ?? ""}</div>
				<L10n.Stylize text={props.text} />
			</div>
			<Filigree.Small />
		</div>
	);
};
